'use strict';
let sessionInfo=null, me=null, editorAxis=0, editQuestionIndex=null, currentRemote=null, editingId=null, editingRevision=0, templateEditingId=null, templates=[];
let busy=false;let guestMode=false,guestName='';
const e=escapeHtml;
function notify(message,error=false){const el=document.getElementById('appNotice');el.className=error?'error-box':'notice-box';el.textContent=message;}
window.addEventListener('error',event=>{notify(event.message||'تعذر إكمال الطلب.',true);});
window.addEventListener('unhandledrejection',event=>{event.preventDefault();notify(event.reason?.message||'تعذر إكمال الطلب.',true);});
async function api(op,data=null,params={}){
 const url='api.php?'+new URLSearchParams({op,...params});const options={credentials:'same-origin',headers:{}};
 if(data!==null){options.method='POST';options.headers['X-CSRF-Token']=sessionInfo?.csrf||'';if(data instanceof FormData)options.body=data;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}
 const response=await fetch(url,options);let result;try{result=await response.json();}catch{throw new Error('لم يستجب الخادم بصيغة صحيحة. تحققي من التهيئة وسجل الأخطاء.');}
 if(!response.ok){if(response.status===401&&me){me=null;renderAccount();authScreen();}throw new Error(result.error||'تعذر تنفيذ الطلب.');}return result;
}
function clearView(){if(advanceTimer)clearTimeout(advanceTimer);currentAppState='portal';navBar.style.display='none';progressContainer.style.visibility='hidden';btnReset.style.display='none';document.getElementById('appNotice').textContent='';}
const surveyBackViews=[];
function rememberSurveyView(){const screen=stage.querySelector('.screen');if(!screen)return;surveyBackViews.push({nodes:[...stage.childNodes],scroll:screen.scrollTop,appState:currentAppState,model:structuredClone(customSurvey),active:structuredClone(activeSurvey),response:structuredClone(state),remote:currentRemote,axis:editorAxis,question:editQuestionIndex,id:editingId,revision:editingRevision,template:templateEditingId,nav:navBar.style.cssText,progress:progressContainer.style.cssText,reset:btnReset.style.cssText});if(surveyBackViews.length>20)surveyBackViews.shift();}
function portal(content){rememberSurveyView();clearView();stage.innerHTML='<section class="screen active"><div class="portal"><div class="portal-back-row"><button class="portal-back-button" onclick="surveyGoBack()">↩ عودة للخلف</button></div>'+content+'</div></section>';}
function surveyGoBack(){if(currentAppState==='survey'&&currentScreen>0){goTo(currentScreen-1);return;}const previous=surveyBackViews.pop();if(previous){clearView();customSurvey=previous.model;activeSurvey=previous.active;state=previous.response;currentRemote=previous.remote;editorAxis=previous.axis;editQuestionIndex=previous.question;editingId=previous.id;editingRevision=previous.revision;templateEditingId=previous.template;currentAppState=previous.appState;navBar.style.cssText=previous.nav;progressContainer.style.cssText=previous.progress;btnReset.style.cssText=previous.reset;stage.replaceChildren(...previous.nodes);const screen=stage.querySelector('.screen');if(screen)screen.scrollTop=previous.scroll;return;}if(history.length>1){history.back();return;}buildHomeScreen();}
function renderAccount(){if(me)setSchool({...me,use_default_logo:me.default_school&&!me.logo_key});document.getElementById('accountBar').innerHTML=`<div class="madar-header"><div class="dhalim-header-logos"><a class="school-identity" href="/dhalim/" aria-label="الرئيسية مدارس ظليم للبنات"><img src="data:image/png;base64," alt="شعار مدارس ظليم للبنات"></a><img class="madar-vision" src="data:image/png;base64," alt="شعار رؤية 2030"></div><div class="madar-greeting"><span class="greeting-orbit" aria-hidden="true"></span><span>${me?'أهلًا بكِ '+e(me.name):'استبيانات مدار'}</span>${me?'<button class="survey-logout" onclick="logout()">تسجيل الخروج</button>':''}</div></div>${me?`<nav class="madar-nav" aria-label="التنقل الرئيسي"><button onclick="buildHomeScreen()">⌂ الرئيسية</button><button onclick="surveysHub()">استبياناتي</button><button onclick="myBoardScreen()">لوحتي</button><button onclick="analysisHub()">تحليلي</button><button onclick="mySettingsScreen()">إعداداتي</button>${sessionInfo.auth_mode==='standalone'?'<button onclick="logout()">خروج</button>':''}</nav>`:''}`;}
function authScreen(mode='login'){
 if(sessionInfo?.auth_mode==='madar'){
  const login=new URL(sessionInfo.login_url,location.href);
  if(login.origin!==location.origin)throw new Error('يجب أن يكون مسار تسجيل دخول مدار على النطاق نفسه.');
  login.searchParams.set('return_to',location.pathname+location.search);
  location.replace(login.href);return;
 }
 const register=mode==='register',reset=mode==='reset',request=mode==='forgot'||mode==='resend';
 const title={login:'تسجيل الدخول',register:'حساب معلمة جديد',forgot:'استعادة كلمة المرور',resend:'إعادة إرسال تأكيد البريد',reset:'تعيين كلمة مرور جديدة'}[mode];
 portal(`<div class="portal-card"><h1>${title}</h1><form id="authForm">${register?'<label class="field">اسم المعلمة<input name="name" required maxlength="160" autocomplete="name"></label><label class="field">اسم المدرسة<input name="school_name" required maxlength="200"></label>':''}${!reset?'<label class="field">البريد الإلكتروني<input dir="ltr" type="email" name="email" required maxlength="191" autocomplete="email"></label>':''}${!request?`<label class="field">كلمة المرور<input type="password" name="password" required ${register||reset?'minlength="12"':''} maxlength="200" autocomplete="${mode==='login'?'current-password':'new-password'}"></label>`:''}<div class="portal-actions"><button type="submit">${title}</button></div></form><div id="authMessage" class="auth-message" role="status"></div><div class="portal-actions"><button onclick="authScreen('login')">دخول</button><button onclick="authScreen('register')">إنشاء حساب</button><button onclick="authScreen('forgot')">نسيت كلمة المرور</button></div></div>`);
 document.getElementById('authForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const data=Object.fromEntries(new FormData(event.target));if(reset)data.token=new URLSearchParams(location.search).get('reset');const result=await api(mode,data);if(mode==='login'){sessionInfo.csrf=result.csrf;me=result.user;renderAccount();await route();}else{document.getElementById('authMessage').textContent=result.message;if(reset){history.replaceState({},'',location.pathname);}}}catch(err){notify(err.message,true);}finally{button.disabled=false;}};
}
async function logout(){const buttons=document.querySelectorAll('.survey-logout');buttons.forEach(b=>b.disabled=true);try{if(sessionInfo?.auth_mode==='madar'){const scope=sessionInfo?.native_role||'teacher';const accountResponse=await fetch('/api/'+scope+'/me',{credentials:'same-origin',cache:'no-store'});const account=await accountResponse.json();if(!accountResponse.ok)throw new Error(account.error||'تعذر التحقق من الجلسة');const response=await fetch('/api/'+scope+'/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':account.csrfToken||sessionStorage.getItem('madar-csrf')||''},body:'{}'});const result=await response.json();if(!response.ok)throw new Error(result.error||'تعذر تسجيل الخروج');sessionStorage.removeItem('madar-csrf');location.replace('/surveys/public/login.php');return;}await api('logout',{});me=null;sessionInfo=await api('session');renderAccount();authScreen();}catch(error){notify(error.message||'تعذر تسجيل الخروج، حاولي مرة أخرى.',true);}finally{buttons.forEach(b=>b.disabled=false);}}
buildHomeScreen=function(){if(!me||me.is_guest)return authScreen();portal(`<section class="madar-home"><p class="home-eyebrow">مساحة للتطوير ومشاركة الأثر</p><h1>بوابة مجمع مدارس ظليم</h1><p class="home-intro">كل رأي يصنع فرقًا، وكل نتيجة تفتح بابًا للتحسين.</p><div class="home-tiles"><button class="home-tile" onclick="surveysHub()"><span class="tile-icon"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="6" y="5" width="20" height="24" rx="4"/><path d="M12 5V3h8v2M11 12h10M11 18h10M11 24h6"/></svg></span><strong>استبياناتي</strong><span>لتقييم المعلمات</span><i aria-hidden="true">←</i></button><button class="home-tile" onclick="myBoardScreen()"><span class="tile-icon"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="3" y="3" width="11" height="11" rx="3"/><rect x="18" y="3" width="11" height="11" rx="3"/><rect x="3" y="18" width="11" height="11" rx="3"/><rect x="18" y="18" width="11" height="11" rx="3"/></svg></span><strong>لوحتي</strong><span>مساحة لطالباتي</span><i aria-hidden="true">←</i></button><button class="home-tile" onclick="analysisHub()"><span class="tile-icon"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 4v24h24M11 22v-8M18 22V8M25 22V3"/></svg></span><strong>تحليلي</strong><span>قراءة النتائج والتقارير</span><i aria-hidden="true">←</i></button></div></section>`);};
async function surveysHub(){const icon=path=>'<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+path+'</svg>';portal('<section class="survey-tools survey-hub-pastel"><p class="tools-kicker">أدواتك في مدار</p><h1>استبيانات</h1><p class="tools-intro">اختاري خطوتك التالية بكل سهولة.</p><div class="survey-tool-grid"><button class="survey-tool" onclick="goToSelectReady()"><span class="tool-art">'+icon('<rect x="7" y="5" width="18" height="24" rx="3"/><path d="M12 5V3h8v2M11 13l3 3 7-7M11 22h10"/>')+'</span><strong>الاستبيان الجاهز</strong><span>قوالب جاهزة لتبدئي بسهولة</span><i aria-hidden="true">استعراض القوالب ←</i></button><button class="survey-tool" onclick="newCustom()"><span class="tool-art">'+icon('<path d="M18 5H7a3 3 0 0 0-3 3v18a3 3 0 0 0 3 3h18a3 3 0 0 0 3-3V15M14 18l2-6L26 2l4 4-10 10-6 2zM23 5l4 4M9 23h10"/>')+'</span><strong>إعداد الاستبيان</strong><span>صمّمي أسئلتك بأسلوبك</span><i aria-hidden="true">بدء الإعداد ←</i></button><button class="survey-tool" onclick="listSurveyFiles()"><span class="tool-art">'+icon('<path d="M3 10V7a3 3 0 0 1 3-3h7l4 5h9a3 3 0 0 1 3 3v14a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V10zM3 12h26M10 19h12M10 23h8"/>')+'</span><strong>ملفات الاستبيان</strong><span>استبياناتك ومشاركاتها وتقاريرها</span><i aria-hidden="true">عرض الملفات ←</i></button></div><div id="surveyInbox"></div></section>');await loadSurveyInbox();}
async function analysisHub(){portal('');}
goToSelectReady=async function(){templates=(await api("templates")).items;portal('<section class="survey-tools"><h1>تقييم الاستبيانة</h1><p class="tools-intro">اختاري نوع التقييم.</p><div class="survey-tool-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))">'+templates.filter(t=>Number(t.active)).map(t=>{const workshop=/ورشة/.test(t.name);const label=workshop?"ورشة عمل":/الدرس/.test(t.name)?"الدرس التطبيقي":t.name;const paths=workshop?'<circle cx="11" cy="9" r="4"/><circle cx="23" cy="11" r="3"/><path d="M3 27v-4a8 8 0 0 1 16 0v4M21 19a6 6 0 0 1 8 6v2M10 24l3 3 6-7"/>':'<path d="M3 5h26v17H3zM10 29l6-7 6 7M16 22v7M9 15l4-4 4 3 6-6"/>';return `<button class="survey-tool" onclick="chooseTemplate(${Number(t.id)})"><span class="tool-art"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg></span><strong>${e(label)}</strong><span>${workshop?"تقييم تجربة الورشة وأثرها":"تقييم الممارسات التعليمية وأثر الدرس"}</span><i aria-hidden="true">استخدام القالب ←</i></button>`;}).join("")+'</div></section>');};
function setSchool(s){SCHOOL_NAME=s.school_name||'';SCHOOL_LOGO=s.logo_key?'logo.php?'+new URLSearchParams({key:s.logo_key,survey:s.id||'',token:new URLSearchParams(location.search).get('s')||''}):s.use_default_logo?ORIGINAL_SCHOOL_LOGO:'';document.getElementById('topSchoolLogo').src=SCHOOL_LOGO||'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg"/%3E';document.getElementById('topSchoolLogo').style.visibility=SCHOOL_LOGO?'visible':'hidden';document.getElementById('topVisionLogo').src=VISION_2030_LOGO;}
function editorModel(){return{title:'استبيان مخصص',teacher:me.name,lesson:'',kind:'custom',performance:false,school_name:me.school_name||(me.default_school?me.default_school_name:''),axes:[{name:'المحور الأول',qs:[]}]};}
function newCustom(){editingId=null;editingRevision=0;templateEditingId=null;editorAxis=0;editQuestionIndex=null;customSurvey=editorModel();goToBuilder();}
function chooseTemplate(id){const t=templates.find(x=>Number(x.id)===id);if(!t)return;newCustom();customSurvey={...editorModel(),title:t.name,kind:t.kind,performance:t.kind!=='custom',axes:JSON.parse(t.definition).axes};renderBuilder();}
startSurvey=function(type){const t=templates.find(x=>x.kind===type);if(t)chooseTemplate(Number(t.id));};
const sourceGoToBuilder=goToBuilder;
goToBuilder=function(){rememberSurveyView();document.getElementById('appNotice').textContent='';sourceGoToBuilder();};
const sourceRenderBuilder=renderBuilder;
renderBuilder=function(){
 customSurvey.teacher=me.name;customSurvey.school_name=me.school_name;sourceRenderBuilder();document.getElementById('bTeacher').readOnly=true;document.getElementById('bTeacher').closest('label').hidden=true;
 const identityBox=document.createElement('aside');identityBox.className='survey-identity-box';identityBox.setAttribute('aria-label','بيانات المعلمة والمدرسة');identityBox.innerHTML='<p class="identity-caption">بيانات مرتبطة بحسابك</p><dl><div><dt>اسم المعلمة</dt><dd>'+e(me.name)+'</dd></div><div><dt>اسم المدرسة</dt><dd>'+e(me.school_name)+'</dd></div></dl>';stage.querySelector('.builder-title').after(identityBox);
 const ready=!templateEditingId&&customSurvey.kind!=='custom';
 if(ready){const card=stage.querySelector('.builder-card');card.querySelector('.builder-title').textContent='إعداد إرسال الاستبيان';document.getElementById('bTeacher').previousElementSibling.textContent='اسم المعلمة';card.querySelector('.add-q-row').previousElementSibling.hidden=true;card.querySelector('.add-q-row').hidden=true;card.querySelector('.q-list').hidden=true;card.querySelector('.builder-actions').innerHTML='<button class="btn-start" onclick="prepareSurveySend()">إرسال الاستبيان</button><button class="btn-start" onclick="previewDraft()">معاينة الاستبيان</button>';return;}

 const card=stage.querySelector('.builder-card'),extras=document.createElement('div');extras.className='builder-extras';
 extras.innerHTML=`<label>اسم المدرسة<input id="bSchool" readonly maxlength="200" value="${e(customSurvey.school_name||'')}"></label><label><input type="checkbox" id="bPerformance" ${customSurvey.performance?'checked':''}> تقييم أداء (يمنع تقييم الذات)</label><p class="question-pages">كل سؤال صفحة مستقلة؛ تحفظ المحاور وترتيب الأسئلة عند النشر.</p><label>المحور الحالي<select id="bAxis">${customSurvey.axes.map((a,i)=>`<option value="${i}" ${i===editorAxis?'selected':''}>${e(a.name)}</option>`).join('')}</select></label><label>اسم المحور<input id="bAxisName" maxlength="200" value="${e(customSurvey.axes[editorAxis].name)}"></label><div class="portal-actions"><button onclick="addAxis()">إضافة محور</button><button onclick="removeAxis()">حذف المحور الحالي</button></div><label>نوع إجابة السؤال الجديد<select id="bType"><option value="rating3">لا / نوعًا ما / نعم</option><option value="rating5">مقياس 1 إلى 5</option><option value="choice">اختيارات مخصصة (لا تدخل في درجة الأداء)</option></select></label><label id="customOptions" hidden>الاختيارات مفصولة بعلامة |<input id="bOptions" value="الخيار الأول|الخيار الثاني" maxlength="1200"></label><label><input type="checkbox" id="bReverse"> سؤال سلبي (عكس درجة الأداء)</label><p>الشعار من ملف مدرستك. يمكنك رفعه من «مدرستي وشعاري» قبل حفظ المسودة.</p>`;
 card.insertBefore(extras,card.querySelector('.add-q-row'));['bSchool','bAxis','bAxisName'].forEach(id=>document.getElementById(id).closest('label').hidden=true);extras.querySelector('.portal-actions').hidden=true;
 document.getElementById('bSchool').oninput=ev=>customSurvey.school_name=ev.target.value;
 document.getElementById('bPerformance').onchange=ev=>customSurvey.performance=ev.target.checked;
 document.getElementById('bAxisName').oninput=ev=>customSurvey.axes[editorAxis].name=ev.target.value;
 document.getElementById('bAxis').onchange=ev=>{editorAxis=Number(ev.target.value);editQuestionIndex=null;renderBuilder();};
 document.getElementById('bType').onchange=ev=>{document.getElementById('customOptions').hidden=ev.target.value!=='choice';document.getElementById('bReverse').disabled=ev.target.value==='choice';};
 stage.querySelectorAll('.q-item').forEach((row,i)=>{const b=document.createElement('button');b.textContent='تعديل';b.onclick=()=>editQuestion(i);row.append(b);});
 const actions=card.querySelector('.builder-actions');actions.innerHTML=templateEditingId?'<button class="btn-start" onclick="saveTemplate()">حفظ تعديلات القالب</button>':'<button class="btn-start" onclick="saveDraft()">حفظ المسودة</button><button class="btn-start" onclick="previewDraft()">معاينة الأسئلة</button>';
};
function addAxis(){if(customSurvey.axes.length>=30)throw new Error('الحد الأقصى 30 محورًا.');customSurvey.axes.push({name:'محور جديد',qs:[]});editorAxis=customSurvey.axes.length-1;editQuestionIndex=null;renderBuilder();}
function removeAxis(){if(customSurvey.axes.length===1)throw new Error('يلزم محور واحد على الأقل.');if(!confirm('حذف المحور وجميع أسئلته؟'))return;customSurvey.axes.splice(editorAxis,1);editorAxis=0;editQuestionIndex=null;renderBuilder();}
function editQuestion(i){const q=customSurvey.axes[editorAxis].qs[i];editQuestionIndex=i;document.getElementById('newQText').value=q.text;document.getElementById('bType').value=q.type||'rating3';document.getElementById('bOptions').value=q.options.join('|');document.getElementById('bReverse').checked=!!q.reverse;document.getElementById('bType').dispatchEvent(new Event('change'));stage.querySelector('.btn-add').textContent='حفظ السؤال';document.getElementById('newQText').focus();}
addQuestion=function(){const text=document.getElementById('newQText').value.trim();if(!text)return;const type=document.getElementById('bType').value;const options=type==='rating3'?[...TRI]:type==='rating5'?['1','2','3','4','5']:document.getElementById('bOptions').value.split('|').map(x=>x.trim()).filter(Boolean);if(options.length<2||options.length>10||new Set(options).size!==options.length)throw new Error('أضيفي بين خيارين و10 خيارات مختلفة.');const q={text,type,options,reverse:type!=='choice'&&document.getElementById('bReverse').checked};if(editQuestionIndex===null)customSurvey.axes[editorAxis].qs.push(q);else customSurvey.axes[editorAxis].qs[editQuestionIndex]=q;editQuestionIndex=null;renderBuilder();};
deleteQuestion=function(i){customSurvey.axes[editorAxis].qs.splice(i,1);editQuestionIndex=null;renderBuilder();};
async function saveDraft(){if(busy)return;busy=true;try{const result=await api('save',{...customSurvey,id:editingId,revision:editingRevision});editingId=result.survey.id;editingRevision=result.survey.revision;customSurvey=result.survey;await listMine();notify('تم حفظ المسودة على الخادم.');}finally{busy=false;}}
function previewDraft(){activeSurvey=structuredClone(customSurvey);currentRemote=null;setSchool({...customSurvey,logo_key:me.logo_key,use_default_logo:me.default_school&&!me.logo_key});initSurveyEngine();state.reviewerName=me.name;document.getElementById('reviewerName').value=me.name;notify('معاينة المسودة فقط؛ لا تُحفظ إجابات قبل نشر الاستبيان.');}
async function editDraft(id){const result=await api('get',null,{id});customSurvey=result.survey;editingId=id;editingRevision=customSurvey.revision;templateEditingId=null;editorAxis=0;editQuestionIndex=null;goToBuilder();}
async function publishSurvey(id){if(!confirm('بعد النشر تثبت الأسئلة ولا يمكن تعديلها. هل تريدين النشر؟'))return;await api('publish',{id});await shareSurvey(id);}
async function closeSurvey(id){if(!confirm('إغلاق الاستبيان وإيقاف استقبال الإجابات؟'))return;await api('close',{id});await listMine();}
function surveyButtons(s){return `<div class="portal-actions">${s.status==='draft'?`<button onclick="shareSurvey(${Number(s.id)})">إرسال الاستبيان</button>`:''}${s.status==='published'?`<button onclick="shareSurvey(${Number(s.id)})">الرابط وQR</button><button onclick="closeSurvey(${Number(s.id)})">إغلاق</button>`:''}<button onclick="showResults(${Number(s.id)})">تحليل النتائج / PDF</button><button onclick="duplicateSurvey(${Number(s.id)})">تكرار</button><button onclick="trashSurvey(${Number(s.id)})">حذف</button></div>`;}
async function listMine(){const data=await api('mine');portal('<h1>استبياناتي وتحليلها</h1>'+data.items.map(s=>`<div class="portal-card"><h2>${e(s.title)}</h2><p>${statusName(s.status)} · المشاركات: ${Number(s.responses)}</p>${surveyButtons(s)}</div>`).join('')+(data.items.length?'':'<p>لم تنشئي استبيانات بعد.</p>'));}
function statusName(status){return{draft:'مسودة',published:'منشور',closed:'مغلق'}[status]||status;}
async function duplicateSurvey(id){const s=(await api('get',null,{id})).survey;newCustom();customSurvey={...s,id:null,title:s.title+' — نسخة',teacher:me.name,school_name:me.school_name||s.school_name};renderBuilder();}
async function shareSurveyLink(id){const s=(await api('get',null,{id})).survey;const url=new URL('/dhalim/',location.origin).href+'?s='+encodeURIComponent(s.share_token);portal(`<div class="portal-card"><h1>مشاركة الاستبيان</h1><h2>${e(s.title)}</h2><p>يفتح الرابط اختيار الدخول كزائر بالاسم أو كمعلمة بحساب مدار.</p><input id="shareUrl" dir="ltr" readonly value="${e(url)}"><div class="portal-actions"><button onclick="copyShare()">نسخ الرابط</button><button onclick="downloadQR()">تنزيل رمز QR</button></div><div class="qr-box" id="shareQR"></div></div>`);document.getElementById('shareQR').innerHTML=makeQR(url);}
async function copyShare(){const field=document.getElementById('shareUrl');try{await navigator.clipboard.writeText(field.value);notify('تم نسخ الرابط.');}catch{field.select();notify('حددي الرابط وانسخيه من الحقل.');}}
function downloadQR(){const svg=document.querySelector('#shareQR svg');if(!svg)return;const url=URL.createObjectURL(new Blob([svg.outerHTML],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='madar-survey-qr.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function openShared(token){const result=await api('open',null,{token});currentRemote=result.survey;activeSurvey=structuredClone(currentRemote);setSchool(activeSurvey);initSurveyEngine();state.reviewerName=me.name;document.getElementById('reviewerName').value=me.name;}
submitSurvey=async function(){
 if(!currentRemote){notify('هذه معاينة. احفظي المسودة وانشريها لاستقبال الإجابات.',true);return;}
 if(busy)return;const missing=ALL_Q.find(q=>state.answers[q.id]===undefined);if(missing){goTo(missing.num);notify('أجيبي عن جميع الأسئلة.',true);return;}
 if(!document.getElementById('identityConsent').checked){goTo(TOTAL_Q+1);notify('يلزم الموافقة على شروط وسياسات الموقع.',true);return;}
 busy=true;btnNext.disabled=true;
 try{await api(guestMode?'guest_submit':'submit',{id:currentRemote.id,token:new URLSearchParams(location.search).get('s'),answers:state.answers,notes:state.notes,identity_consent:true});goTo(TOTAL_Q+3);}
 catch(err){notify(err.message,true);}finally{busy=false;updateNav();}
};
async function listParticipated(){const result=await api('participated');portal('<h1>الاستبيانات التي شاركت فيها</h1>'+result.items.map(s=>{const answers=JSON.parse(s.answers),qs=getQuestions(JSON.parse(s.definition));return `<details class="portal-card"><summary>${e(s.title)} · ${e(s.teacher)} · ${e(s.submitted_at)} UTC</summary>${qs.map(q=>`<p>${e(q.text)}: <b>${e(q.options[answers[q.id]]??'—')}</b></p>`).join('')}<p>${e(s.notes)}</p></details>`;}).join('')+(result.items.length?'':'<p>لا توجد مشاركات سابقة.</p>'));}
async function showResults(id){const r=await api('results',null,{id});clearView();currentAppState='analysis';setSchool(r.survey);const data=computeAggregate(r.survey,r.responses);renderAggregateReport(r.survey,data,false);stage.querySelector('[data-original-legend]')?.remove();const legend=document.createElement('div');legend.className='sheet-legend';legend.textContent='لا: أحمر · نوعًا ما: أصفر · نعم: أخضر. المقياس الخماسي يتدرج من الأحمر إلى الأخضر؛ الخيارات الأخرى موضحة تحت كل سؤال.';stage.querySelector('.sheet-heading')?.after(legend);data.questions.forEach((q,i)=>{const row=stage.querySelectorAll('.chart-row')[i];if(!row)return;const opts=document.createElement('div');opts.style.cssText='grid-column:1 / -1;font-size:.8rem;color:#52675f';opts.textContent=q.options.map((opt,j)=>opt+': '+q.counts[j]+' ('+(q.answered?(100*q.counts[j]/q.answered).toFixed(1):'0')+'%)').join(' · ');row.append(opts);});const rec=document.createElement('div');rec.className='insight-panel';rec.innerHTML='<h3>التوصيات المستندة إلى النتائج</h3>';const ul=document.createElement('ul');const low=data.axes.filter(a=>a.score!==null&&a.score<70);for(const a of low){const li=document.createElement('li');li.textContent='وضع خطة تحسين لمحور «'+a.name+'» ومراجعة الأسئلة الأقل تقييمًا وإعادة القياس بعد التنفيذ.';ul.append(li);}if(!low.length){const li=document.createElement('li');li.textContent=data.totalScored?'تعزيز الممارسات الأعلى تقييمًا، ومراجعة ملاحظات المشاركات ومتابعة المؤشرات في قياس لاحق.':'جمع إجابات رقمية كافية قبل إصدار توصيات أداء.';ul.append(li);}rec.append(ul);stage.querySelector('.compact-bottom')?.after(rec);if(!SCHOOL_LOGO)stage.querySelectorAll('.official-school').forEach(el=>{el.innerHTML='<span class="school-placeholder">'+e(SCHOOL_NAME)+'</span>';});}
function mySettingsScreen(){if(!me||me.is_guest)return authScreen();portal(`<div class="portal-card personal-settings"><h1>إعداداتي</h1><dl><dt>الاسم</dt><dd>${e(me.name)}</dd><dt>إيميل منصة مدرستي</dt><dd dir="ltr">${e(me.email)}</dd><dt>الحساب</dt><dd>${me.is_admin?'مالكة الموقع':'معلمة'}</dd></dl><p>تُدار بيانات الدخول من حسابك الأساسي في مدار.</p><div class="portal-actions"><a class="settings-account-link" href="${me.is_admin?'/owner/dashboard.php':'/teacher/index.html'}">إعدادات حسابي في مدار ←</a>${me.is_admin?'<button onclick="profileScreen()">مدرستي وشعاري</button>':''}</div></div>`);}
async function profileScreen(){if(!me?.is_admin){notify("هذا القسم خاص بمالكة الموقع.",true);return;}portal(`<div class="portal-card"><h1>مدرستي وشعاري</h1><label class="field">اسم المدرسة<input id="profileSchool" maxlength="200" value="${e(me.school_name)}"></label><button onclick="saveProfile()">حفظ اسم المدرسة</button><form id="logoForm"><label class="field">شعار المدرسة (PNG أو JPEG، حتى 2 ميغابايت)<input type="file" name="logo" accept="image/png,image/jpeg" required></label><button>رفع الشعار</button></form><p>تُستخدم البيانات في المسودات عند حفظها. تبقى بيانات الاستبيانات المنشورة ثابتة.</p></div>`);document.getElementById('logoForm').onsubmit=async ev=>{ev.preventDefault();const r=await api('upload_logo',new FormData(ev.target));me.logo_key=r.logo_key;notify('تم حفظ شعار المدرسة.');};}
async function saveProfile(){if(!me?.is_admin)return;const school_name=document.getElementById('profileSchool').value;await api('profile',{school_name});me.school_name=school_name;notify('تم حفظ اسم المدرسة.');}
async function adminScreen(){location.replace('/owner/dashboard');}
async function adminUsers(){const r=await api('admin_users');portal('<h1>حسابات المعلمات</h1><p>تُعرض أحدث 1000 حساب. صلاحيات الإدارة تُضبط من نظام مدار أو أداة التثبيت.</p>'+r.items.map(u=>`<div class="portal-card"><b>${e(u.name)}</b> · ${e(u.email)}<p>تأكيد البريد غير مطلوب · ${Number(u.active)?'مفعل':'معطل'}</p>${Number(u.id)!==me.id&&!Number(u.is_admin)?`<button onclick="toggleUser(${Number(u.id)},${Number(u.active)?'false':'true'})">${Number(u.active)?'تعطيل':'تفعيل'}</button>`:''}</div>`).join(''));}
async function toggleUser(id,active){await api('set_user',{id,active});await adminUsers();}
async function adminSurveys(){const r=await api('admin_surveys');portal('<h1>جميع الاستبيانات</h1><p>أحدث 1000 استبيان.</p>'+r.items.map(s=>`<div class="portal-card"><h2>${e(s.title)}</h2><p>${e(s.teacher)} · ${statusName(s.status)} · ${Number(s.responses)} مشاركة</p>${surveyButtons(s)}</div>`).join(''));}
async function adminTemplates(){templates=(await api('templates')).items;portal('<h1>إدارة القوالب</h1><button onclick="newTemplate()">إضافة قالب</button>'+templates.map(t=>`<div class="portal-card"><h2>${e(t.name)}</h2><p>${Number(t.active)?'متاح':'مخفي'}</p><button onclick="editTemplate(${Number(t.id)})">تعديل</button><button onclick="toggleTemplate(${Number(t.id)})">${Number(t.active)?'إخفاء':'إتاحة'}</button></div>`).join(''));}
function newTemplate(){newCustom();templateEditingId=-1;customSurvey.title='قالب جديد';renderBuilder();}
function editTemplate(id){const t=templates.find(x=>Number(x.id)===id);newCustom();templateEditingId=id;customSurvey={...editorModel(),title:t.name,kind:t.kind,axes:JSON.parse(t.definition).axes};renderBuilder();}
async function saveTemplate(){await api('save_template',{...customSurvey,id:templateEditingId>0?templateEditingId:0,name:customSurvey.title,active:true});templateEditingId=null;await adminTemplates();notify('تم حفظ القالب.');}
async function toggleTemplate(id){const t=templates.find(x=>Number(x.id)===id);await api('save_template',{id,name:t.name,kind:t.kind,...JSON.parse(t.definition),active:!Number(t.active)});await adminTemplates();}
async function adminSettings(){const r=await api('settings');const open=r.items.find(x=>x.setting_key==='registration_open')?.setting_value==='1';portal(`<div class="portal-card"><h1>إعدادات النظام</h1><p>نظام الحسابات: ${e(r.auth_mode)}. بيانات الاتصال والبريد وتحديد حساب مدرسة ظليم تُدار في إعدادات الخادم.</p><label><input type="checkbox" id="registrationOpen" ${open?'checked':''}> السماح بإنشاء حسابات مستقلة جديدة</label><p>يطبق هذا الخيار في الوضع المستقل فقط.</p><button onclick="saveSettings()">حفظ الإعدادات</button></div>`);}
async function saveSettings(){await api('save_settings',{registration_open:document.getElementById('registrationOpen').checked});notify('تم حفظ الإعدادات.');}
async function route(){const token=new URLSearchParams(location.search).get('s');if(token)return sharedEntry(token);if(!me||me.is_guest)return authScreen();if(new URLSearchParams(location.search).get('view')==='admin'&&me.is_admin)return adminScreen();buildHomeScreen();}
// Printing expands only the visible report and restores the user's disclosure state.
let printDetails=[];
window.addEventListener('beforeprint',()=>{printDetails=[...stage.querySelectorAll('details')].map(el=>[el,el.open]);printDetails.forEach(([el])=>el.open=true);});
window.addEventListener('afterprint',()=>printDetails.forEach(([el,open])=>el.open=open));
(async()=>{try{sessionInfo=await api('session');me=sessionInfo.user;renderAccount();const params=new URLSearchParams(location.search);if(params.has('verify')){const r=await api('verify',{token:params.get('verify')});params.delete('verify');history.replaceState({},'',location.pathname+(params.size?'?'+params:''));sessionInfo=await api('session');me=sessionInfo.user;renderAccount();await route();notify(r.message);return;}if(params.has('reset')){authScreen('reset');return;}if(params.get('board')==='1'){if(document.readyState==='loading')await new Promise(resolve=>document.addEventListener('DOMContentLoaded',resolve,{once:true}));myBoardScreen();return;}await route();}catch(err){portal('<div class="portal-card"><h1>استبيانات مدار</h1><p class="error-box">'+e(err.message)+'</p></div>');}})();

async function prepareSurveySend(){if(busy)return;busy=true;try{const result=await api('save',{...customSurvey,id:editingId,revision:editingRevision});editingId=result.survey.id;editingRevision=result.survey.revision;customSurvey=result.survey;await shareSurvey(editingId);}catch(err){notify(err.message,true);}finally{busy=false;}}
async function shareSurvey(id){const s=(await api('get',null,{id})).survey;portal(`<div class="portal-card"><h1>إرسال الاستبيان</h1><h2>${e(s.title)}</h2><p>اختاري طريقة الإرسال. عند المتابعة تُعتمد الأسئلة ويُفتح الاستبيان لاستقبال التقييمات.</p><div class="portal-actions"><button onclick="sendSurveyMode(${Number(id)},'link')">إرسال برابط</button><button onclick="sendSurveyMode(${Number(id)},'teachers')">إرسال إلى معلمات ظليم</button></div></div>`);}
async function sendSurveyMode(id,mode){try{if(mode==='teachers')return await chooseSurveyTeachers(id);const s=(await api('get',null,{id})).survey;if(s.status==='draft'){await api('publish',{id});}await shareSurveyLink(id);}catch(err){notify(err.message,true);}}
async function chooseSurveyTeachers(id){const result=await api('survey_teachers');portal(`<div class="portal-card"><h1>إرسال إلى معلمات ظليم</h1><p>سيظهر الاستبيان داخل «استبياناتي» لدى المعلمات المختارات.</p><form id="surveyRecipients">${result.items.map(t=>`<label class="identity-consent"><input type="checkbox" name="teacher" value="${Number(t.id)}"> ${e(t.name)}</label>`).join('')||'<p>لا توجد معلمات مفعّلات متاحات للإرسال.</p>'}<div class="portal-actions"><button type="submit" ${result.items.length?'':'disabled'}>إرسال إلى المعلمات المختارات</button></div></form></div>`);document.getElementById('surveyRecipients').onsubmit=async ev=>{ev.preventDefault();const ids=[...ev.target.querySelectorAll('input:checked')].map(el=>Number(el.value));if(!ids.length)return notify('اختاري معلمة واحدة على الأقل.',true);const btn=ev.submitter;btn.disabled=true;try{const s=(await api('get',null,{id})).survey;if(s.status==='draft')await api('publish',{id});const r=await api('send_survey',{id,teacher_ids:ids});portal('<div class="portal-card"><h1>تم إرسال الاستبيان</h1><p>'+e(r.message)+'</p><button onclick="surveysHub()">العودة إلى استبياناتي</button></div>');}catch(err){notify(err.message,true);btn.disabled=false;}};}
async function loadSurveyInbox(){const container=document.getElementById('surveyInbox');if(!container)return;const r=await api('survey_inbox');if(!container.isConnected)return;container.innerHTML=r.items.length?'<h2 style="margin-top:30px">استبيانات وصلتني</h2>'+r.items.map(s=>`<div class="portal-card"><h3>${e(s.title)}</h3><p>من المعلمة: ${e(s.teacher)}</p><button onclick="location.href='?s=${encodeURIComponent(s.share_token)}'">بدء التقييم</button></div>`).join(''):'';}

const backInitSurveyEngine=initSurveyEngine;
initSurveyEngine=function(){rememberSurveyView();return backInitSurveyEngine(...arguments);};
const backShowResults=showResults;
showResults=async function(id){rememberSurveyView();return await backShowResults(id);};
function ensureSurveyBackButton(){const screen=stage.querySelector('.screen.active')||stage.querySelector('.screen');if(!screen||screen.querySelector('.portal-back-button'))return;const row=document.createElement('div');row.className='portal-back-row survey-page-back';const button=document.createElement('button');button.type='button';button.className='portal-back-button';button.textContent='↩ عودة للخلف';button.onclick=surveyGoBack;row.append(button);screen.prepend(row);}
new MutationObserver(ensureSurveyBackButton).observe(stage,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});ensureSurveyBackButton();

async function sharedEntry(token){guestMode=false;const info=await api('guest_info',null,{token});document.getElementById('accountBar').style.display='none';portal(`<section class="survey-tools"><h1>مشاركة الاستبيان</h1><h2>${e(info.title)}</h2><p class="tools-intro">اختاري طريقة الدخول إلى الاستبيان.</p><div class="survey-tool-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr))"><button class="survey-tool" onclick="guestNameScreen()"><span class="tool-art" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="16" cy="10" r="6"/><path d="M5 29v-3a11 11 0 0 1 22 0v3"/></svg></span><strong>دخول كزائر</strong><span>المشاركة بكتابة الاسم</span><i>متابعة ←</i></button><button class="survey-tool" onclick="sharedTeacherEntry()"><span class="tool-art" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 10L16 3l14 7-14 7L2 10zM8 14v9c5 5 11 5 16 0v-9M29 11v12"/></svg></span><strong>دخول كمعلمة</strong><span>المشاركة بحساب مدار</span><i>تسجيل الدخول ←</i></button></div></section>`);}
async function sharedTeacherEntry(){guestMode=false;if(me&&!me.is_guest){document.getElementById('accountBar').style.display='';return openShared(new URLSearchParams(location.search).get('s'));}const login=new URL(sessionInfo.login_url,location.href);login.searchParams.set('return_to',location.pathname+location.search);location.assign(login.href);}
function guestNameScreen(){portal(`<div class="portal-card"><h1>دخول كزائر</h1><form id="guestNameForm"><label class="field">اسم الزائر<input id="guestEntryName" autocomplete="name" required minlength="2" maxlength="160" value="${e(guestName)}"></label><p>يُسجَّل التقييم بالاسم المدخل، ويظهر لصاحبة الاستبيان.</p><button type="submit">بدء التقييم</button></form></div>`);document.getElementById('guestNameForm').onsubmit=async ev=>{ev.preventDefault();ev.submitter.disabled=true;try{const result=await api('guest_start',{token:new URLSearchParams(location.search).get('s'),name:document.getElementById('guestEntryName').value.trim()});guestName=result.name;if(!me)me={name:guestName,is_guest:true};guestMode=true;currentRemote=result.survey;activeSurvey=structuredClone(result.survey);setSchool(activeSurvey);initSurveyEngine();state.reviewerName=me?.name||guestName;document.getElementById('reviewerName').value=state.reviewerName;document.getElementById('reviewerName').previousElementSibling.textContent=me.is_guest?'اسم الزائر':'اسم المقيمة من حسابك';}catch(err){notify(err.message,true);ev.submitter.disabled=false;}};}

async function listSurveyFiles(){const data=await api('mine');portal('<section class="survey-tools"><h1>ملفات الاستبيانات</h1>'+data.items.map(s=>`<div class="portal-card"><h2><button class="survey-file-title" onclick="openSurveyFile(${Number(s.id)})">استبيان (${e(s.lesson||s.title||'غير محدد')})</button></h2><p>${statusName(s.status)} · المشاركات: ${Number(s.responses)}</p>${surveyButtons(s)}</div>`).join('')+(data.items.length?'':'<div class="portal-card">لا توجد استبيانات محفوظة بعد.</div>')+'</section>');}

function myBoardScreen(){portal('');}

async function openSurveyFile(id){const s=(await api('get',null,{id})).survey;const mine=await api('mine');const item=mine.items.find(x=>Number(x.id)===Number(id));portal(`<section class="survey-tools"><h1>${e(s.title)}</h1><div class="portal-card"><p>المعلمة: ${e(s.teacher)}</p><p>المدرسة: ${e(s.school_name)}</p><p>${statusName(s.status)} · المشاركات: ${Number(item?.responses||0)}</p>${surveyButtons(s)}</div></section>`);}
async function trashSurvey(id){if(!confirm('نقل الاستبيان إلى المحذوفات؟ يمكنك استعادته بعد الحذف.'))return;try{await api('trash_survey',{id});await listSurveyFiles();const box=document.createElement('div');box.className='notice-box';box.innerHTML='تم حذف الاستبيان من الملفات. <button onclick="restoreSurvey('+Number(id)+')">تراجع عن الحذف</button>';stage.querySelector('.portal').prepend(box);}catch(err){notify(err.message,true);}}
async function restoreSurvey(id){try{await api('restore_survey',{id});await listSurveyFiles();notify('تمت استعادة الاستبيان ومشاركاته.');}catch(err){notify(err.message,true);}}

async function surveyTrashScreen(){const r=await api('survey_trash');portal('<h1>الاستبيانات المحذوفة</h1>'+r.items.map(s=>`<div class="portal-card"><h2>${e(s.title)}</h2><button onclick="restoreSurvey(${Number(s.id)})">استعادة الاستبيان</button></div>`).join('')+(r.items.length?'':'<p>لا توجد استبيانات محذوفة.</p>'));}
